import{_ as i,C as r,c as n,o as l,aj as d,j as t,G as o,a as h,w as g}from"./chunks/framework.Bfdr4H5E.js";const c="/sk/images/Dual-Auction-LTP-Ask-side.webp",u="/sk/images/Dual-Auction-LTP-Bid-side.webp",p="/sk/images/Dual-Auction-Limit-Bull-Bear.webp",m="/sk/images/Dual-Auction-15-MKT-order.webp",b="/sk/images/Dual-Auction-MKT-order-C.webp",w="/sk/images/Bid-Ask-Spread.webp",f="/sk/images/Dual-Auction-Price-Chart.webp",B=JSON.parse('{"title":"The Dual-Auction Process","description":"","frontmatter":{"outline":"deep","prev":{"text":"Types of Orders","link":"/trading-with-pav/types-of-orders"},"next":{"text":"Supply and Demand","link":"/trading-with-pav/supply-and-demand"}},"headers":[],"relativePath":"trading-with-pav/the-dual-auction-process.md","filePath":"trading-with-pav/the-dual-auction-process.md"}'),y={name:"trading-with-pav/the-dual-auction-process.md"};function k(v,e,A,T,P,q){const a=r("GraphComment"),s=r("ClientOnly");return l(),n("div",null,[e[0]||(e[0]=d('<h1 id="the-dual-auction-process" tabindex="-1">The Dual-Auction Process <a class="header-anchor" href="#the-dual-auction-process" aria-label="Permalink to &quot;The Dual-Auction Process&quot;">​</a></h1><p>In this article we going to learn about The Dual-Auction Process and see how prices really move.</p><div class="info custom-block"><p class="custom-block-title">Table of Contents</p><nav class="table-of-contents"><ul><li><a href="#anatomy-of-dual-auction">Anatomy of Dual Auction</a></li><li><a href="#what-moves-the-price">What moves the Price ?</a></li><li><a href="#bid-–-ask-spread">Bid – Ask Spread</a></li><li><a href="#the-bid-ask-spread-impacted-by">The Bid-Ask Spread Impacted By:</a><ul><li><a href="#liquidity">Liquidity</a></li><li><a href="#volume">Volume</a></li><li><a href="#volatility">Volatility</a></li></ul></li><li><a href="#dual-auction-process-w-price-chart">Dual Auction Process w/ Price Chart</a></li><li><a href="#video">Video</a></li><li><a href="#comments">Comments</a></li></ul></nav></div><p>let’s consider the financial markets. We now have what is know as a the <strong>Dual Auction Process</strong> (also know as <strong>Market Watch</strong> or <strong>Depth of Market</strong>– “<strong>DOM</strong>”)</p><p>Multiple <strong>buyers</strong> competing to <strong>buy</strong> into market, and multiple <strong>sellers</strong> competing to <strong>sell</strong> into market; <strong>all at the same time</strong>.</p><h2 id="anatomy-of-dual-auction" tabindex="-1">Anatomy of Dual Auction <a class="header-anchor" href="#anatomy-of-dual-auction" aria-label="Permalink to &quot;Anatomy of Dual Auction&quot;">​</a></h2><p><img src="'+c+'" alt="Dual-Auction-LTP-Ask-side"></p><p>As you can see <strong>DOM</strong> in the above image some even call it “<strong>Price Ladder</strong>” as price climbs up and down in the “<strong>Price Range</strong>” which can be seen in the center.</p><p>Bidding is shown in “<strong>Bid Column</strong>” in blue color and “<strong>Offers Column</strong>” also know as “<strong>Ask</strong>” are shown in red color. Their total is shown down below respectively as “<strong>Total Bid</strong>” and “<strong>Total Ask</strong>“.</p><p>The “<strong>Last Traded Price</strong>” aka <strong>LTP</strong> is <strong>Current Market Price</strong> which is now at the ask side as it is red color when LTP is at Bid side it turns Blue in color as in below image.</p><p><img src="'+u+'" alt="Dual-Auction-LTP-Bid-side"></p><p>In the above image each bid or ask can be from and individual trader or numerous traders for e.g. in the bid column at the end there is 15 qty at ₹ 49.70 can be from 5 traders bidding 1 contracts each with remaining from 2 different traders bidding 5 contracts each totaling 15 qty.</p><p>So don’t just assume single traders at different price it can be any numerous ways. Also the above dual auction shows <strong>5 bids and 5 ask</strong> at any given moment.</p><p>This is called as “<strong>5 market depth</strong>” or <strong>Level 2</strong> data of volume. In India currently Zerodha is the only retail broker to offer “<strong>20 market depth</strong>” or <strong>Level 3</strong> data to its clients. Want account with Zerodha broker <a href="https://zerodha.com/?c=LR6790&amp;s=CONSOLE" target="_blank" rel="noreferrer">click here</a>.</p><p><img src="'+p+'" alt="Dual-Auction-Limit-Bull-Bear"></p><p>As you can see in the above image all the bids and asks are Limit Orders. The <strong>bid column</strong> displays “<strong>Current Demand</strong>” or “<strong>Bullish Pressure</strong>” and the <strong>ask column</strong> is “<strong>Current Supply</strong>” or “<strong>Bearish Pressure</strong>“.</p><h2 id="what-moves-the-price" tabindex="-1">What moves the Price ? <a class="header-anchor" href="#what-moves-the-price" aria-label="Permalink to &quot;What moves the Price ?&quot;">​</a></h2><p><img src="'+m+'" alt="Dual-Auction-15-MKT-order"></p><p>To understand how prices move up and down just like the previous example we learnt from the 2nd Hand Mobile Auction just take a look at the above image.</p><p>On the bid side we have 25, 4, 3, 16 and 15 qty and <strong>bid price</strong> <strong>starts</strong> from ₹ 49.95 <strong>going down</strong> likewise we have <strong>ask price</strong> from ₹ 50.00 <strong>going up</strong> with 3, 21, 5, 4, 75 qty with LTP currently at ask side. As we know all these bid-ask are limit orders.</p><p>Now let me demonstrate what moves the price. Lets say in the above image the 15 qty bid were to cancel “<strong>Limit order</strong>” and turn it into “<strong>Market order</strong>“. Market order function is to accept whatever price the opposite side has which means this 15 qty bid will accept whatever the ask side has to offer.</p><p>This means that the 15 qty will fill the 1st qty i.e. 3 qty at ₹ 50.00 at which point the remaining qty 12 goes to 21 qty at ₹ 50.05 but only 12 qty gets filled so from 21 qty only 9 qty remains unfilled at 50.05. This happen in fraction of a second. As of March 2022 NSE has the capacity to process 300,000 orders per second and does 12 billion order messages a day, up from 2 billion.</p><p><img src="'+b+'" alt="Dual-Auction-MKT-order-C"></p><p>In the above image you can see that the “<strong>LTP</strong>” jumped up from ₹ 50.00 to ₹ 50.05. This is how prices move with market order. If prices is going down its because sellers are using market orders and accepting any bid value.</p><p><strong>Important Tip</strong></p><p>Never decide whether to go <strong>Long</strong> or <strong>Short</strong> just by analyzing the “<strong>Total bids or Ask</strong>“. like for e.g. in the above image there are Total 98 bids and 141 ask so deciding to go short because ask total is more is stupid idea.</p><p>Because those are Limit orders total. Which can be canceled at any time to fool you. Remember that executed volume is always shown on charts and never on Bid-Ask (DOM). You can never find Buyers or Sellers in the volume because buyer and seller agree and the transaction takes place.</p><p>So in short “<strong>Limit Orders</strong>” are <strong>Passive</strong> and “<strong>Market Orders</strong>” are “<strong>Aggressive</strong>“.</p><h2 id="bid-–-ask-spread" tabindex="-1">Bid – Ask Spread <a class="header-anchor" href="#bid-–-ask-spread" aria-label="Permalink to &quot;Bid – Ask Spread&quot;">​</a></h2><p>The <strong>bid-ask spread</strong> is a representation of the supply and demand for an asset. If the bid and offer prices are <strong>close together</strong>, it is considered a “<strong>tight market</strong>“, which means that there is a consensus between buyers and sellers on how much the asset is worth. If the <strong>spread</strong> is “<strong>wider</strong>“, it means that there is <strong>significant difference in opinion</strong>.</p><p><img src="'+w+'" alt="Bid-Ask-Spread"></p><p><strong>Spread</strong> is <strong>difference</strong> between <strong>ask &amp; bid</strong>, so in the above image the tight market has 0.05 spread and in the wide market 0.20 spread. This spread should be you ideal difference when you enter SL and trigger value. You can see the <strong>Spread value</strong> in between <strong>buy and sell buttons</strong> in <strong>Status Line</strong>.</p><h2 id="the-bid-ask-spread-impacted-by" tabindex="-1">The Bid-Ask Spread Impacted By: <a class="header-anchor" href="#the-bid-ask-spread-impacted-by" aria-label="Permalink to &quot;The Bid-Ask Spread Impacted By:&quot;">​</a></h2><ol><li>Liquidity</li><li>Volume</li><li>Volatility</li></ol><h3 id="liquidity" tabindex="-1">Liquidity <a class="header-anchor" href="#liquidity" aria-label="Permalink to &quot;Liquidity&quot;">​</a></h3><p>This refers to how <strong>easily</strong> an <strong>asset</strong> can be <strong>bought</strong> or <strong>sold</strong>.<br> As the <strong>liquidity</strong> of an <strong>asset increases</strong>, the bid-ask <strong>spread</strong> usually <strong>tightens</strong>.</p><h3 id="volume" tabindex="-1">Volume <a class="header-anchor" href="#volume" aria-label="Permalink to &quot;Volume&quot;">​</a></h3><p>This is a method of reporting the quantity of an asset that is traded daily.<br> Assets that have a <strong>higher trading volume</strong> will often have <strong>narrower bid-ask spreads</strong>.</p><h3 id="volatility" tabindex="-1">Volatility <a class="header-anchor" href="#volatility" aria-label="Permalink to &quot;Volatility&quot;">​</a></h3><p>This is a measure of how much the market price changes in a given period.<br> During periods of <strong>high volatility</strong>, when <strong>prices change rapidly</strong>, the <strong>spread</strong> is usually much <strong>wider</strong>.</p><p>From the above we can tell that Tight or Narrow Spreads are best to trade where as Volatile Markets should not be traded or must be avoided.</p><h2 id="dual-auction-process-w-price-chart" tabindex="-1">Dual Auction Process w/ Price Chart <a class="header-anchor" href="#dual-auction-process-w-price-chart" aria-label="Permalink to &quot;Dual Auction Process w/ Price Chart&quot;">​</a></h2><ul><li><strong>Individual price bars</strong> are the <strong>result</strong> of the <strong>dual auction process</strong> operating within the time-frame of that <strong>price bar</strong>.</li><li>Each <strong>price swing</strong> is the result of the <strong>dual auction process</strong> operating for the <strong>duration of that price swing</strong>.</li><li>Over a period of time, when the <strong>demand</strong> is <strong>consistently greater than supply</strong> “<strong>price</strong>” will <strong>rise</strong> as it did in <strong>swings 1 and 4</strong> (Image below).</li><li>When the <strong>supply</strong> is <strong>consistently greater than demand</strong> “<strong>price</strong>” will <strong>fall</strong> as it did in <strong>swing 3</strong>.</li></ul><p><img src="'+f+'" alt="Dual-Auction-Price-Chart"></p><p>The Sentiment in above chart as follows:</p><ul><li><strong>Bullish sentiment</strong> leads to <strong>bullish order-flow</strong> resulting in price rising, as in swings 1 and 4.</li><li><strong>Bearish sentiment</strong> leads to <strong>bearish orderflow</strong> resulting in price falling, as in swing 3.</li><li><strong>Neutral sentiment</strong> leads to <strong>narrow range sideways price action,</strong> as in range action in 2.</li></ul><p>As we learnt above we don’t have to see or use DOM as it is printed on chart. That’s all there is to The Dual Auction Process, in next article we gonna look into Supply and Demand.</p><h2 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h2><p>Dual Auction - Order Matching</p>',49)),e[1]||(e[1]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/j3rs6GME0I8",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[2]||(e[2]=t("p",null,"Bid – Ask Spread",-1)),e[3]||(e[3]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/BbQetNWS8aA",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[4]||(e[4]=t("p",null,"Dual Auction Process w/ Price Chart",-1)),e[5]||(e[5]=t("iframe",{width:"560",height:"315",src:"https://www.youtube.com/embed/3Eit5Arwujg",title:"YouTube video player",frameborder:"0",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture",allowfullscreen:""},null,-1)),e[6]||(e[6]=t("p",null,"The above video explains this article in hindi language.",-1)),e[7]||(e[7]=t("h2",{id:"comments",tabindex:"-1"},[h("Comments "),t("a",{class:"header-anchor",href:"#comments","aria-label":'Permalink to "Comments"'},"​")],-1)),o(s,null,{default:g(()=>[o(a)]),_:1})])}const S=i(y,[["render",k]]);export{B as __pageData,S as default};
